#include <gtest/gtest.h>

extern "C" {
#include "core/types/base.h"
#include "core/types/tier_array.h"
}

class TierArrayTest : public ::testing::Test {
   protected:
    TierArray array;

    void SetUp() override { TierArrayInit(&array); }

    void TearDown() override { TierArrayDestroy(&array); }
};

static int CompareTiers(const void* a, const void* b) {
    Tier valA = *(const Tier*)a;
    Tier valB = *(const Tier*)b;
    return (valA > valB) - (valA < valB);
}

TEST_F(TierArrayTest, InitializationAndEmptyState) {
    EXPECT_TRUE(TierArrayEmpty(&array));
}

TEST_F(TierArrayTest, InitCopy) {
    EXPECT_TRUE(TierArrayAppend(&array, (Tier)1));
    EXPECT_TRUE(TierArrayAppend(&array, (Tier)2));

    TierArray copied;
    EXPECT_TRUE(TierArrayInitCopy(&copied, &array));
    EXPECT_EQ(copied.size, 2);
    EXPECT_EQ((Tier)copied.array[0], (Tier)1);
    EXPECT_EQ((Tier)copied.array[1], (Tier)2);

    TierArrayDestroy(&copied);
}

TEST_F(TierArrayTest, AppendAndBack) {
    EXPECT_TRUE(TierArrayAppend(&array, (Tier)42));
    EXPECT_FALSE(TierArrayEmpty(&array));
    EXPECT_EQ(TierArrayBack(&array), (Tier)42);
}

TEST_F(TierArrayTest, RemoveUnordered) {
    EXPECT_TRUE(TierArrayAppend(&array, (Tier)10));
    EXPECT_TRUE(TierArrayAppend(&array, (Tier)20));
    EXPECT_TRUE(TierArrayAppend(&array, (Tier)30));

    EXPECT_TRUE(TierArrayRemoveUnordered(&array, (Tier)20));
    EXPECT_FALSE(TierArrayRemoveUnordered(&array, (Tier)99));

    // After removing successfully, the size decreases
    ASSERT_EQ(array.size, 2);
}

TEST_F(TierArrayTest, PopBack) {
    EXPECT_TRUE(TierArrayAppend(&array, (Tier)1));
    EXPECT_TRUE(TierArrayAppend(&array, (Tier)2));
    TierArrayPopBack(&array);
    EXPECT_EQ(TierArrayBack(&array), (Tier)1);
}

TEST_F(TierArrayTest, SortExplicit) {
    EXPECT_TRUE(TierArrayAppend(&array, (Tier)3));
    EXPECT_TRUE(TierArrayAppend(&array, (Tier)1));
    EXPECT_TRUE(TierArrayAppend(&array, (Tier)2));

    TierArraySortExplicit(&array, CompareTiers);

    ASSERT_EQ(array.size, 3);
    EXPECT_EQ((Tier)array.array[0], (Tier)1);
    EXPECT_EQ((Tier)array.array[1], (Tier)2);
    EXPECT_EQ((Tier)array.array[2], (Tier)3);
}
